-- Kiểm tra kết quả sau khi seed
SELECT 
    DATE(("CreatedAt" + INTERVAL '7 hours')) AS ngay_vn,
    COUNT(*) AS tong_luot
FROM "TrafficLogs"
WHERE "CreatedAt" >= '2026-10-22 17:00:00' 
  AND "CreatedAt" <  '2026-10-23 17:00:00'
GROUP BY DATE(("CreatedAt" + INTERVAL '7 hours'));
